// Bass-Swirl (Palette-Starter): Drehung um die Mitte, Bass verstaerkt
vec2 warp(vec2 uv)
{
    vec2 d = uv - 0.5;
    float winkel = 0.30 * sin(uTime * 0.4) + 1.2 * bass * exp(-6.0 * dot(d, d));
    float s = sin(winkel);
    float c = cos(winkel);
    float zoom = 1.0 + 0.03 * sin(uTime * 0.9) + 0.05 * treb;
    return 0.5 + mat2(c, -s, s, c) * d / zoom;
}
